// Studio: collaborative place editor. Fly camera, part placement on a grid,
// selection + properties, live co-editing over WebSocket, game config panel.
import * as THREE from 'three';
import { setupScene, World, createPartMesh } from '../engine/world.js';
import { state, openWS, esc, toast } from '../api.js';

const PART_DEFS = [
  { type: 'block',      label: 'Block',      color: '#a8b6bd', size: [4, 1, 4] },
  { type: 'spawn',      label: 'Spawn',      color: '#cfd8dc', size: [6, 0.5, 6] },
  { type: 'checkpoint', label: 'Checkpoint', color: '#19c2ff', size: [3, 0.5, 3] },
  { type: 'kill',       label: 'Kill Brick', color: '#d40000', size: [4, 0.4, 4] },
  { type: 'coin',       label: 'Coin',       color: '#ffd700', size: [1, 1, 1] },
  { type: 'goal',       label: 'Goal',       color: '#19ff8c', size: [4, 1, 4] },
  { type: 'bounce',     label: 'Bounce',     color: '#ffe14d', size: [3, 1, 3] },
  { type: 'speed',      label: 'Speed Pad',  color: '#19c2ff', size: [4, 0.2, 4] },
  { type: 'water',      label: 'Water',      color: '#2a7de1', size: [8, 3, 8] },
  { type: 'deco',       label: 'Deco',       color: '#8d6e63', size: [2, 2, 2] },
  { type: 'mover',      label: 'Mover',      color: '#9b59b6', size: [4, 1, 4] },
  { type: 'tele',       label: 'Teleporter', color: '#8a4fff', size: [3, 0.6, 3] },
];

const COLOR_PALETTE = ['#a8b6bd', '#e54b4b', '#f0a020', '#ffd23f', '#3aa14f', '#19ff8c', '#2a7de1', '#19c2ff', '#8a4fff', '#ff5e9c', '#8d6e63', '#37474f', '#ffffff', '#1b1b1b'];
const MODES = ['sandbox', 'obby', 'collect', 'tag'];
const GENRES = ['Obby', 'Collecting', 'Tag', 'Social', 'Adventure', 'Fighting', 'Tycoon', 'Other'];

export class Studio {
  constructor(root, gameId, onExit) {
    this.root = root;
    this.gameId = gameId;
    this.onExit = onExit;
    this.tool = 'select';
    this.placeType = 'block';
    this.selId = null;
    this.editors = new Map(); // userId -> {username, color, sel, highlightMesh}
    this.keys = {};
    this.camPos = new THREE.Vector3(20, 18, 20);
    this.camYaw = Math.PI * 0.75;
    this.camPitch = -0.45;
    this.alive = true;
    this.undoStack = [];

    this._buildDOM();
    const { renderer, scene, camera, resize } = setupScene(this.canvas);
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
    this.resizeFn = resize;
    this.world = new World(scene);

    // placement ghost + grid + selection box
    this.ghost = null;
    this.grid = new THREE.GridHelper(200, 200, 0x3a606f, 0x24414e);
    this.grid.position.y = 0.01;
    scene.add(this.grid);
    this.selBox = new THREE.Box3Helper(new THREE.Box3(), 0xffd23f);
    this.selBox.visible = false;
    scene.add(this.selBox);

    this.raycaster = new THREE.Raycaster();
    this.groundPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);

    this._connect();
    this._bindInput();
    this._loop();
  }

  // ---------------- DOM ----------------
  _buildDOM() {
    this.root.innerHTML = `
      <div id="studio-topbar">
        <span class="title">🔧 Studio</span>
        <span id="st-gamename" style="color:var(--dim)"></span>
        <button class="tool-btn" data-tool="select">Select (1)</button>
        <button class="tool-btn" data-tool="place">Place (2)</button>
        <button class="tool-btn" data-tool="delete">Delete (3)</button>
        <span class="spacer"></span>
        <span id="st-editors" class="row" style="gap:6px"></span>
        <button class="tool-btn" id="st-test">▶ Test</button>
        <button class="tool-btn" id="st-exit">Exit</button>
      </div>
      <div id="studio-main">
        <div id="studio-canvas-wrap"><canvas></canvas></div>
        <div id="studio-side">
          <h3>Parts</h3>
          <div class="part-palette" id="st-palette"></div>
          <h3>Properties</h3>
          <div id="st-props"><div style="color:var(--dim)">Nothing selected</div></div>
          <h3>Game Config</h3>
          <div id="st-config"></div>
          <h3>Team Chat</h3>
          <div id="studio-chat-log"></div>
          <input id="st-chat-input" type="text" placeholder="Message collaborators…" maxlength="200">
        </div>
      </div>
    `;
    this.canvas = this.root.querySelector('canvas');
    this.sideEl = this.root.querySelector('#studio-side');
    this.propsEl = this.root.querySelector('#st-props');
    this.configEl = this.root.querySelector('#st-config');
    this.editorsEl = this.root.querySelector('#st-editors');

    const palette = this.root.querySelector('#st-palette');
    for (const def of PART_DEFS) {
      const b = document.createElement('button');
      b.className = 'tool-btn';
      b.textContent = def.label;
      b.style.borderLeft = `4px solid ${def.color}`;
      b.onclick = () => { this.placeType = def.type; this.setTool('place'); this._refreshPalette(); };
      b.dataset.type = def.type;
      palette.appendChild(b);
    }
    this.root.querySelectorAll('[data-tool]').forEach((b) => {
      b.onclick = () => this.setTool(b.dataset.tool);
    });
    this.root.querySelector('#st-exit').onclick = () => this.exit();
    this.root.querySelector('#st-test').onclick = () => {
      this.exit('#/play/' + this.gameId);
    };
    const chatInput = this.root.querySelector('#st-chat-input');
    chatInput.addEventListener('keydown', (e) => {
      e.stopPropagation();
      if (e.key === 'Enter') {
        const text = chatInput.value.trim();
        if (text) this._send({ t: 'chat', text });
        chatInput.value = '';
      }
    });
    this.setTool('select');
  }

  _refreshPalette() {
    this.root.querySelectorAll('#st-palette .tool-btn').forEach((b) => {
      b.classList.toggle('active', this.tool === 'place' && b.dataset.type === this.placeType);
    });
  }

  setTool(tool) {
    this.tool = tool;
    this.root.querySelectorAll('[data-tool]').forEach((b) => b.classList.toggle('active', b.dataset.tool === tool));
    this._refreshPalette();
    if (tool !== 'place' && this.ghost) { this.scene.remove(this.ghost); this.ghost = null; }
    this.canvas.style.cursor = tool === 'delete' ? 'not-allowed' : tool === 'place' ? 'copy' : 'default';
  }

  // ---------------- networking ----------------
  _connect() {
    this.ws = openWS();
    this.ws.onopen = () => this.ws.send(JSON.stringify({ t: 'studio', gameId: this.gameId }));
    this.ws.onclose = () => {
      if (this.alive) { toast('Studio disconnected', 'red'); this.exit(); }
    };
    this.ws.onmessage = (ev) => {
      let msg;
      try { msg = JSON.parse(ev.data); } catch (e) { return; }
      this._handle(msg);
    };
  }

  _send(msg) {
    if (this.ws && this.ws.readyState === 1) this.ws.send(JSON.stringify(msg));
  }

  _handle(msg) {
    switch (msg.t) {
      case 'error':
        toast(msg.error, 'red');
        break;
      case 'sjoined': {
        this.selfId = msg.selfId;
        this.meta = msg.meta;
        this.config = msg.config;
        this.isOwner = msg.isOwner;
        this.world.load(msg.world.parts);
        this.root.querySelector('#st-gamename').textContent = msg.meta.name;
        for (const ed of msg.editors) if (ed.id !== this.selfId) this._addEditor(ed);
        this._renderEditors();
        this._renderConfig();
        break;
      }
      case 'sjoin':
        this._addEditor(msg.editor);
        this._renderEditors();
        toast(`${msg.editor.username} joined Studio`);
        break;
      case 'sleave': {
        const ed = this.editors.get(msg.id);
        if (ed && ed.highlightMesh) this.scene.remove(ed.highlightMesh);
        this.editors.delete(msg.id);
        this._renderEditors();
        break;
      }
      case 'sel': {
        const ed = this.editors.get(msg.id);
        if (ed) { ed.sel = msg.partId; this._updateRemoteHighlight(ed); }
        break;
      }
      case 'op':
        this._applyRemoteOp(msg.op);
        break;
      case 'opok':
        // server confirmation; part ids may have been rewritten on add
        if (msg.op.kind === 'add' && this._lastLocalAdd && msg.op.part.id !== this._lastLocalAdd) {
          this.world.removePart(this._lastLocalAdd);
          this.world.addPart(msg.op.part);
          this._lastLocalAdd = null;
        }
        break;
      case 'chat': {
        const log = this.root.querySelector('#studio-chat-log');
        const div = document.createElement('div');
        div.innerHTML = `<b>${esc(msg.username)}:</b> ${esc(msg.text)}`;
        log.appendChild(div);
        while (log.children.length > 40) log.firstChild.remove();
        log.scrollTop = log.scrollHeight;
        break;
      }
    }
  }

  _addEditor(ed) {
    this.editors.set(ed.id, Object.assign({ highlightMesh: null }, ed));
    this._updateRemoteHighlight(this.editors.get(ed.id));
  }

  _renderEditors() {
    let html = '';
    for (const ed of this.editors.values()) {
      html += `<span class="editor-chip"><span class="dot" style="background:${ed.color}"></span>${esc(ed.username)}</span>`;
    }
    this.editorsEl.innerHTML = html || '<span style="color:var(--dim);font-size:12px">solo session</span>';
  }

  _updateRemoteHighlight(ed) {
    if (ed.highlightMesh) { this.scene.remove(ed.highlightMesh); ed.highlightMesh = null; }
    if (!ed.sel) return;
    const part = this.world.parts.get(ed.sel);
    if (!part) return;
    const box = new THREE.Box3(
      new THREE.Vector3(part.x - part.sx / 2 - 0.05, part.y - part.sy / 2 - 0.05, part.z - part.sz / 2 - 0.05),
      new THREE.Vector3(part.x + part.sx / 2 + 0.05, part.y + part.sy / 2 + 0.05, part.z + part.sz / 2 + 0.05)
    );
    ed.highlightMesh = new THREE.Box3Helper(box, new THREE.Color(ed.color));
    this.scene.add(ed.highlightMesh);
  }

  _applyRemoteOp(op) {
    if (op.kind === 'add' || op.kind === 'update') {
      this.world.addPart(op.part);
      if (this.selId === op.part.id) this._select(op.part.id); // refresh props
    } else if (op.kind === 'del') {
      this.world.removePart(op.partId);
      if (this.selId === op.partId) this._select(null);
    } else if (op.kind === 'meta') {
      this.meta = { name: op.data.name, desc: op.data.desc, genre: op.data.genre, public: op.data.public };
      this.config = op.data.config;
      this.root.querySelector('#st-gamename').textContent = op.data.name;
      this._renderConfig();
    }
    // refresh any remote highlight tied to that part
    for (const ed of this.editors.values()) this._updateRemoteHighlight(ed);
  }

  // ---------------- ops ----------------
  _opAdd(part) {
    this._lastLocalAdd = part.id;
    this.world.addPart(part);
    this._send({ t: 'op', op: { kind: 'add', part } });
    this.undoStack.push({ kind: 'del', partId: part.id });
  }

  _opUpdate(part, recordUndo = true) {
    if (recordUndo) {
      const prev = this.world.parts.get(part.id);
      if (prev) this.undoStack.push({ kind: 'update', part: { ...prev } });
    }
    this.world.addPart(part);
    this._send({ t: 'op', op: { kind: 'update', part } });
  }

  _opDel(partId) {
    const prev = this.world.parts.get(partId);
    if (prev) this.undoStack.push({ kind: 'add', part: { ...prev } });
    this.world.removePart(partId);
    this._send({ t: 'op', op: { kind: 'del', partId } });
    if (this.selId === partId) this._select(null);
  }

  _undo() {
    const op = this.undoStack.pop();
    if (!op) return;
    if (op.kind === 'add') { this.world.addPart(op.part); this._send({ t: 'op', op }); }
    else if (op.kind === 'update') { this.world.addPart(op.part); this._send({ t: 'op', op }); }
    else if (op.kind === 'del') { this.world.removePart(op.partId); this._send({ t: 'op', op }); this._select(null); }
  }

  // ---------------- selection & props ----------------
  _select(partId) {
    this.selId = partId;
    this._send({ t: 'sel', partId });
    const part = partId ? this.world.parts.get(partId) : null;
    if (!part) {
      this.selBox.visible = false;
      this.propsEl.innerHTML = '<div style="color:var(--dim)">Nothing selected</div>';
      return;
    }
    this.selBox.box.set(
      new THREE.Vector3(part.x - part.sx / 2, part.y - part.sy / 2, part.z - part.sz / 2),
      new THREE.Vector3(part.x + part.sx / 2, part.y + part.sy / 2, part.z + part.sz / 2)
    );
    this.selBox.visible = true;
    this._renderProps(part);
  }

  _renderProps(part) {
    const num = (name, val, step = 0.5) =>
      `<input type="number" data-prop="${name}" value="${val}" step="${step}">`;
    let extra = '';
    if (part.type === 'mover') {
      extra = `<h3>Mover Path</h3><div class="prop-grid">
        ${num('dx', part.dx ?? 0)}${num('dy', part.dy ?? 0)}${num('dz', part.dz ?? 0)}</div>
        <label class="fld">Period (s)${num('period', part.period ?? 4, 0.5)}</label>`;
    } else if (part.type === 'tele') {
      extra = `<label class="fld">Channel (pairs teleporters)${num('channel', part.channel ?? 1, 1)}</label>`;
    } else if (part.type === 'checkpoint') {
      extra = `<label class="fld">Stage number${num('stage', part.stage ?? 1, 1)}</label>`;
    }
    let swatches = COLOR_PALETTE.map((c) =>
      `<span class="swatch${c === part.color ? ' sel' : ''}" data-color="${c}" style="background:${c}"></span>`).join('');
    this.propsEl.innerHTML = `
      <div style="font-weight:700;margin-bottom:8px">${esc(part.type)} <span style="color:var(--dim);font-weight:400">${esc(part.id)}</span></div>
      <div style="color:var(--dim);margin:6px 0 2px">Position</div>
      <div class="prop-grid">${num('x', part.x)}${num('y', part.y)}${num('z', part.z)}</div>
      <div style="color:var(--dim);margin:6px 0 2px">Size</div>
      <div class="prop-grid">${num('sx', part.sx)}${num('sy', part.sy)}${num('sz', part.sz)}</div>
      <div style="color:var(--dim);margin:6px 0 2px">Color</div>
      <div class="color-swatches">${swatches}</div>
      ${extra}
      <button class="btn red" style="margin-top:10px;width:100%" id="prop-del">Delete part</button>
    `;
    this.propsEl.querySelectorAll('input[data-prop]').forEach((inp) => {
      inp.addEventListener('change', () => {
        const p = { ...this.world.parts.get(part.id) };
        if (!p.id) return;
        p[inp.dataset.prop] = Number(inp.value);
        this._opUpdate(p);
        this._select(p.id);
      });
      inp.addEventListener('keydown', (e) => e.stopPropagation());
    });
    this.propsEl.querySelectorAll('.swatch').forEach((sw) => {
      sw.onclick = () => {
        const p = { ...this.world.parts.get(part.id) };
        p.color = sw.dataset.color;
        this._opUpdate(p);
        this._select(p.id);
      };
    });
    this.propsEl.querySelector('#prop-del').onclick = () => this._opDel(part.id);
  }

  // ---------------- config panel ----------------
  _renderConfig() {
    const m = this.meta, c = this.config;
    this.configEl.innerHTML = `
      <label class="fld">Name<input type="text" id="cfg-name" value="${esc(m.name)}" maxlength="50"></label>
      <label class="fld">Description<textarea id="cfg-desc" rows="3" maxlength="1000">${esc(m.desc)}</textarea></label>
      <label class="fld">Genre<select id="cfg-genre">${GENRES.map((g) => `<option${g === m.genre ? ' selected' : ''}>${g}</option>`).join('')}</select></label>
      <label class="fld">Game mode<select id="cfg-mode">${MODES.map((x) => `<option${x === c.mode ? ' selected' : ''}>${x}</option>`).join('')}</select></label>
      <label class="fld">Max players per server<input type="number" id="cfg-max" value="${c.maxPlayers}" min="1" max="50"></label>
      <label class="fld">Gravity<input type="number" id="cfg-grav" value="${c.gravity}" min="5" max="200"></label>
      <label class="fld">Walk speed<input type="number" id="cfg-walk" value="${c.walkSpeed}" min="4" max="40"></label>
      <label class="fld">Jump power<input type="number" id="cfg-jump" value="${c.jumpPower}" min="5" max="60"></label>
      <label class="fld">Respawn time (s)<input type="number" id="cfg-respawn" value="${c.respawnTime}" min="0" max="10" step="0.5"></label>
      <label class="fld" style="display:flex;align-items:center;gap:8px">
        <input type="checkbox" id="cfg-public" style="width:auto"${m.public ? ' checked' : ''}> Public (listed on Discover)
      </label>
      <button class="btn green" style="width:100%" id="cfg-save">Save config</button>
    `;
    this.configEl.querySelectorAll('input,textarea,select').forEach((el) =>
      el.addEventListener('keydown', (e) => e.stopPropagation()));
    this.configEl.querySelector('#cfg-save').onclick = () => {
      const g = (id) => this.configEl.querySelector(id);
      this._send({
        t: 'op',
        op: {
          kind: 'meta',
          data: {
            name: g('#cfg-name').value,
            desc: g('#cfg-desc').value,
            genre: g('#cfg-genre').value,
            public: g('#cfg-public').checked,
            config: {
              mode: g('#cfg-mode').value,
              maxPlayers: Number(g('#cfg-max').value),
              gravity: Number(g('#cfg-grav').value),
              walkSpeed: Number(g('#cfg-walk').value),
              jumpPower: Number(g('#cfg-jump').value),
              respawnTime: Number(g('#cfg-respawn').value),
            },
          },
        },
      });
      toast('Config saved');
    };
  }

  // ---------------- input / camera ----------------
  _bindInput() {
    this._onKeyDown = (e) => {
      if (/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)) return;
      this.keys[e.code] = true;
      if (e.code === 'Digit1') this.setTool('select');
      if (e.code === 'Digit2') this.setTool('place');
      if (e.code === 'Digit3') this.setTool('delete');
      if (e.code === 'Delete' || e.code === 'Backspace') { if (this.selId) this._opDel(this.selId); }
      if (e.code === 'KeyZ' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); this._undo(); }
      if (e.code === 'KeyD' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        const src = this.selId && this.world.parts.get(this.selId);
        if (src) {
          const copy = { ...src, id: 'c' + Math.random().toString(36).slice(2, 9), x: src.x + src.sx + 0.5 };
          this._opAdd(copy);
          this._select(copy.id);
        }
      }
    };
    this._onKeyUp = (e) => { this.keys[e.code] = false; };
    addEventListener('keydown', this._onKeyDown);
    addEventListener('keyup', this._onKeyUp);

    let lookDrag = false, moveDrag = null, lx = 0, ly = 0, downAt = 0;
    this.canvas.addEventListener('mousedown', (e) => {
      lx = e.clientX; ly = e.clientY; downAt = Date.now();
      if (e.button === 2) { lookDrag = true; return; }
      if (e.button === 0 && this.tool === 'select' && this.selId) {
        // start dragging selected part horizontally if clicked on it
        const hit = this._pickPart(e);
        if (hit && hit.id === this.selId) {
          const part = this.world.parts.get(this.selId);
          moveDrag = { startY: part.y, grabOffset: null };
          return;
        }
      }
    });
    addEventListener('mouseup', (e) => {
      lookDrag = false;
      if (moveDrag) { moveDrag = null; return; }
      if (Date.now() - downAt > 250 || Math.hypot(e.clientX - lx, e.clientY - ly) > 6) return;
      // click action
      if (e.target !== this.canvas) return;
      if (this.tool === 'select') {
        const hit = this._pickPart(e);
        this._select(hit ? hit.id : null);
      } else if (this.tool === 'delete') {
        const hit = this._pickPart(e);
        if (hit) this._opDel(hit.id);
      } else if (this.tool === 'place' && this.ghost) {
        const def = PART_DEFS.find((d) => d.type === this.placeType);
        const part = {
          id: 'c' + Math.random().toString(36).slice(2, 9),
          type: def.type,
          x: this.ghost.position.x, y: this.ghost.position.y, z: this.ghost.position.z,
          sx: def.size[0], sy: def.size[1], sz: def.size[2],
          color: def.color,
        };
        if (def.type === 'mover') Object.assign(part, { dx: 6, dy: 0, dz: 0, period: 4 });
        if (def.type === 'tele') part.channel = 1;
        if (def.type === 'checkpoint') {
          part.stage = 1 + [...this.world.parts.values()].filter((p) => p.type === 'checkpoint').length;
        }
        this._opAdd(part);
      }
    });
    addEventListener('mousemove', (e) => {
      const dx = e.clientX - lx, dy = e.clientY - ly;
      if (lookDrag) {
        this.camYaw -= dx * 0.005;
        this.camPitch = Math.min(1.4, Math.max(-1.4, this.camPitch - dy * 0.005));
        lx = e.clientX; ly = e.clientY;
        return;
      }
      lx = e.clientX; ly = e.clientY;
      if (moveDrag && this.selId) {
        const part = { ...this.world.parts.get(this.selId) };
        if (!part.id) return;
        const pt = this._rayToPlane(e, part.y - part.sy / 2);
        if (pt) {
          part.x = Math.round(pt.x * 2) / 2;
          part.z = Math.round(pt.z * 2) / 2;
          if (this.keys.ShiftLeft || this.keys.ShiftRight) {
            // shift-drag = raise/lower instead
            part.x = this.world.parts.get(this.selId).x;
            part.z = this.world.parts.get(this.selId).z;
            part.y = Math.round((moveDrag.startY - dy * 0.05) * 2) / 2;
          }
          this._opUpdate(part, false);
          this._select(part.id);
        }
        return;
      }
      if (this.tool === 'place') this._updateGhost(e);
    });
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    this.canvas.addEventListener('wheel', (e) => {
      // dolly forward/back
      const dir = new THREE.Vector3();
      this.camera.getWorldDirection(dir);
      this.camPos.addScaledVector(dir, -e.deltaY * 0.02);
      e.preventDefault();
    }, { passive: false });
  }

  _ndc(e) {
    const r = this.canvas.getBoundingClientRect();
    return new THREE.Vector2(
      ((e.clientX - r.left) / r.width) * 2 - 1,
      -((e.clientY - r.top) / r.height) * 2 + 1
    );
  }

  _pickPart(e) {
    this.raycaster.setFromCamera(this._ndc(e), this.camera);
    const hits = this.raycaster.intersectObjects([...this.world.meshes.values()]);
    return hits.length ? hits[0].object.userData.part : null;
  }

  _rayToPlane(e, planeY) {
    this.raycaster.setFromCamera(this._ndc(e), this.camera);
    const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -planeY);
    const out = new THREE.Vector3();
    return this.raycaster.ray.intersectPlane(plane, out) ? out : null;
  }

  _updateGhost(e) {
    const def = PART_DEFS.find((d) => d.type === this.placeType);
    if (!this.ghost || this.ghost.userData.type !== def.type) {
      if (this.ghost) this.scene.remove(this.ghost);
      this.ghost = createPartMesh({
        id: '_ghost', type: def.type,
        x: 0, y: 0, z: 0,
        sx: def.size[0], sy: def.size[1], sz: def.size[2],
        color: def.color, dx: 0, dy: 0, dz: 0, period: 4,
      });
      this.ghost.userData.type = def.type;
      this.ghost.traverse((o) => { if (o.material) { o.material = o.material.clone(); o.material.transparent = true; o.material.opacity = 0.5; } });
      this.scene.add(this.ghost);
    }
    // stack on hovered part top, else ground plane
    this.raycaster.setFromCamera(this._ndc(e), this.camera);
    const hits = this.raycaster.intersectObjects([...this.world.meshes.values()]);
    let x, y, z;
    if (hits.length) {
      const hp = hits[0].object.userData.part;
      const pt = hits[0].point;
      x = pt.x; z = pt.z;
      y = hp.y + hp.sy / 2 + def.size[1] / 2;
    } else {
      const pt = this._rayToPlane(e, 0);
      if (!pt) return;
      x = pt.x; z = pt.z;
      y = def.size[1] / 2;
    }
    this.ghost.position.set(Math.round(x * 2) / 2, Math.round(y * 2) / 2, Math.round(z * 2) / 2);
  }

  // ---------------- loop ----------------
  _loop() {
    let last = performance.now();
    const animate = (now) => {
      if (!this.alive) return;
      this.raf = requestAnimationFrame(animate);
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      this.resizeFn();

      // fly camera
      const speed = (this.keys.ShiftLeft ? 40 : 18) * dt;
      const fwd = new THREE.Vector3(-Math.sin(this.camYaw), 0, -Math.cos(this.camYaw));
      const right = new THREE.Vector3(-fwd.z, 0, fwd.x);
      const active = document.activeElement;
      if (!/INPUT|TEXTAREA|SELECT/.test(active.tagName)) {
        if (this.keys.KeyW) this.camPos.addScaledVector(fwd, speed);
        if (this.keys.KeyS) this.camPos.addScaledVector(fwd, -speed);
        if (this.keys.KeyA) this.camPos.addScaledVector(right, -speed);
        if (this.keys.KeyD) this.camPos.addScaledVector(right, speed);
        if (this.keys.KeyE || this.keys.Space) this.camPos.y += speed;
        if (this.keys.KeyQ || this.keys.ControlLeft) this.camPos.y -= speed;
      }
      this.camera.position.copy(this.camPos);
      this.camera.rotation.set(0, 0, 0);
      this.camera.rotateY(this.camYaw);
      this.camera.rotateX(this.camPitch);

      this.world.tick(dt, null);

      // keep selection box following movers/edits
      if (this.selId) {
        const part = this.world.parts.get(this.selId);
        if (part) {
          const c = this.world.partCenter(part);
          this.selBox.box.set(
            new THREE.Vector3(c.x - part.sx / 2, c.y - part.sy / 2, c.z - part.sz / 2),
            new THREE.Vector3(c.x + part.sx / 2, c.y + part.sy / 2, c.z + part.sz / 2)
          );
        }
      }

      this.renderer.render(this.scene, this.camera);
    };
    this.raf = requestAnimationFrame(animate);
  }

  exit(to) {
    if (!this.alive) return;
    this.alive = false;
    cancelAnimationFrame(this.raf);
    removeEventListener('keydown', this._onKeyDown);
    removeEventListener('keyup', this._onKeyUp);
    try { this.ws.close(); } catch (e) {}
    this.renderer.dispose();
    this.onExit(to);
  }
}
